```json
{
  "decision": "ALLOW|DENY|REQUIRE_APPROVAL",
  "policy_bundle": "sha256:...",
  "reasons": ["POL-R2-APPROVAL"],
  "constraints": {"capabilities": [], "expires_at": "ISO-8601"}
